INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 127, 'Qual é a condição necessária e suficiente para que uma função seja invertível (bijetora)?', 'A função deve ser simultaneamente injetora e sobrejetora');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 127, 'Em uma função, quem é o Domínio e quem é a Imagem?', 'Domínio são os valores de entrada (x); Imagem são os resultados de saída (y).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 126, 'Quanto é 25% de um valor?', ' É a quarta parte desse valor (basta dividir por 4).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 127, ' O que significa a Interseção (A ∩ B) entre dois conjuntos?', 'São apenas os elementos que os dois conjuntos têm em comum (repetidos).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 128, 'Qual é o resultado de |−8| e de |+8|?', ' Ambos valem 8 (o módulo sempre deixa o número positivo).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 129, 'Qual é o valor de log₁₀(100)?', '2 (porque 10² = 100).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 130, 'Como se calcula a área de um triângulo qualquer?', 'A = (base × altura) ÷ 2');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 131, 'No triângulo retângulo, como se calcula o Seno de um ângulo?', 'Seno = Cateto Oposto ÷ Hipotenusa');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 132, 'O que é uma matriz 2 × 3?', 'É uma tabela de números com 2 linhas e 3 colunas.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 133, 'O que significa resolver um sistema linear com duas equações (x e y)?', 'Encontrar o par de números (x, y) que deixa as duas contas verdadeiras ao mesmo tempo.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 134, 'Como se calcula o volume de uma caixa (paralelepípedo)?', 'V = comprimento × largura × altura');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 135, 'Qual é a diferença entre PA e PG?', 'Na PA você vai somando um valor fixo; na PG você vai multiplicando por um valor fixo.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 136, 'Quanto vale 4!', '4 × 3 × 2 × 1 = 24');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 137, 'Qual é a fórmula básica de probabilidade?', 'P = (O que eu quero) ÷ (Total de possibilidades)');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 138, 'Como se calcula a Média Aritmética de 3 notas?', 'Soma as 3 notas e divide o resultado por 3.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 139, 'No plano cartesiano, qual coordenada vem primeiro no par ordenado: x ou y?', 'Primeiro vem o x (horizontal) e depois o y (vertical): (x, y).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 140, 'No número complexo z = 3 + 4i, quem é a parte real e quem é a parte imaginária?', 'Parte real = 3; Parte imaginária = 4 (o número que acompanha o i).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 141, 'Qual é o grau do polinômio P(x) = 5x³ + 2x - 1?', 'Grau 3 (é sempre o maior expoente da letra x).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 174, 'O que significa \"ler nas entrelinhas\" em um texto?', 'É conseguir entender as ideias implícitas (o que o autor quis dizer mas não escreveu diretamente).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 158, 'Qual é a diferença básica entre linguagem verbal e não verbal?', 'Verbal usa palavras (fala ou escrita); Não verbal usa imagens, gestos ou símbolos.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 159, 'Quantas são as classes de palavras (classes gramaticais) na língua portuguesa?', 'São 10 classes (6 variáveis e 4 invariáveis).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 160, 'O que indicam as três conjugações dos verbos (-ar, -er, -ir)?', 'Indicam a terminação do verbo no infinitivo (1ª, 2ª e 3ª conjugação).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 161, 'Qual é a função principal dos pronomes pessoais do caso reto (eu, tu, ele...)?', 'Funcionam como o sujeito da oração (quem pratica a ação).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 162, 'Qual é a função de uma conjunção em uma frase?', 'Ligar orações ou palavras, estabelecendo uma relação de sentido (ex: oposição, causa, conclusão).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 163, 'Qual é a diferença fundamental entre Sujeito e Predicado?', 'Sujeito é quem faz ou sofre a ação; Predicado é tudo o que se diz sobre o sujeito.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 164, 'O que diz a regra básica da concordância verbal?', 'O verbo deve concordar com o seu sujeito em número (singular/plural) e pessoa (1ª, 2ª, 3ª).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 165, 'O que é a crase?', 'É a fusão da preposição \"a\" com o artigo feminino \"a\" (indicada pelo acento grave à).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 166, 'Qual é a diferença entre uma frase, uma oração e um período?', 'Frase tem sentido completo; Oração gira em torno de um verbo; Período é a frase formada por uma ou mais orações.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 167, 'Podemos separar o sujeito do predicado usando vírgula?', 'Não! Nunca se separa o sujeito do predicado por vírgula.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 168, 'O que é o radical de uma palavra?', 'É a parte base da palavra que carrega o seu significado principal (ex: em pedra, pedreiro, o radical é pedr-).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 169, 'Qual é a diferença entre Fonema e Letra?', 'Letra é o símbolo gráfico (o que escrevemos); Fonema é o som que emitimos ao falar.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 170, 'Por que a mudança de uma regra gramatical (como a pontuação) pode mudar o sentido de um texto?', 'Porque a gramática organiza a lógica e a hierarquia das ideias na frase.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 171, 'Qual é o foco principal da Função Emotiva (ou Expressiva)?', 'É transmitir os sentimentos, emoções e opiniões do próprio emissor (uso de 1ª pessoa).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 172, 'Qual é a diferença entre Metáfora e Comparação?', 'A Comparação usa elementos comparativos explícitos (como, tal qual); a Metáfora é uma comparação implícita, sem esses conectivos.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 173, 'Quando devemos usar a linguagem coloquial (popular)?', 'Em situações informais do dia a dia, como conversas com amigos e familiares, mensagens de texto ou redes sociais.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 174, 'O que é a contextualização de um texto?', 'É analisar a época, o local e o objetivo em que o texto foi escrito para entender melhor o seu real significado.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 175, 'O sentido de uma palavra isolada pode mudar dependendo do contexto?', 'Sim! Uma mesma palavra pode ter significados totalmente diferentes dependendo da frase ou situação em que é usada.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 176, 'Qual é a diferença principal entre uma Receita Culinária e uma Notícia Jornalística?', 'A Receita tem o objetivo de instruir (gênero instrucional); a Notícia tem o objetivo de informar sobre um fato real (gênero jornalístico).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 60, 'O que é a Biologia?', 'É a ciência que estuda a vida e os seres vivos em todas as suas formas.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 61, 'Qual é a ordem correta das principais categorias taxonômicas (do maior para o menor)?', 'Reino, Filo, Classe, Ordem, Família, Gênero e Espécie.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 62, 'Qual é a diferença entre Habitat e Nicho Ecológico?', 'Habitat é o \"endereço\" (onde o organismo vive); Nicho ecológico é o seu \"modo de vida\" (o papel que ele desempenha no ecossistema).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 63, 'Qual é o maior bioma brasileiro em extensão territorial?', 'O Amazônia (seguido pelo Cerrado).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 64, 'Qual é a principal função da molécula de ATP nas células?', 'Armazenar e fornecer energia para as reações celulares.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 65, 'Qual é a principal diferença entre células procariontes e eucariontes?', 'As procariontes não têm núcleo organizado (como as bactérias); as eucariontes possuem um núcleo verdadeiro delimitado por membrana.\n\n');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 66, 'Onde ocorre a fotossíntese nas células vegetais?', 'Nos cloroplastos, utilizando a luz solar, água e gás carbônico.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 67, 'Os vírus são considerados seres vivos?', 'Não, pois não possuem estrutura celular própria e só se reproduzem dentro de uma célula hospedeira.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 68, 'O que é o DNA?', 'É a molécula que carrega a informação genética e as instruções para o funcionamento dos seres vivos.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 69, 'O que são organismos transgênicos?', 'São organismos que receberam material genético de outra espécie por meio de manipulação humana.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 70, 'Qual é a principal vantagem da reprodução sexuada em relação à assexuada?', 'A variabilidade genética, que ajuda na adaptação e evolução das espécies.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 71, 'O que é um zigoto?', 'É a célula inicial formada pela união do espermatozoide com o óvulo (fecundação).\n\n');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 72, 'O que é um tecido biológico?', 'É um conjunto de células semelhantes que trabalham juntas para realizar uma função específica.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 73, 'Qual é a principal função do sistema respiratório?', 'Realizar as trocas gasosas (absorver oxigênio e eliminar gás carbônico).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 74, 'O que propõe a teoria da Seleção Natural de Charles Darwin?', 'Que os indivíduos mais bem adaptados ao ambiente têm mais chances de sobreviver e deixar descendentes.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 75, 'Para que servem os estômatos nas folhas das plantas?', 'Para realizar as trocas gasosas e a transpiração da planta.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 76, 'Qual reino da biologia engloba os fungos (como cogumelos, leveduras e mofos)?', 'O Reino Fungi.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 77, 'Qual é a principal característica que diferencia os animais vertebrados dos invertebrados?', 'A presença de coluna vertebral e crânio ósseo ou cartilaginoso.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 78, 'O que diferencia a respiração pulmonar da respiração branquial?', 'branquial retira o oxigênio dissolvido na água (peixes); a pulmonar retira o oxigênio do ar atmosférico (mamíferos, aves, répteis).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 79, 'Qual é a diferença básica entre uma doença endêmica e uma epidemia?', 'Endemia é uma doença típica e constante de uma região; Epidemia é um surto que se espalha rapidamente por várias regiões afetando muitas pessoas.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 142, 'Qual é a principal diferença entre Tempo e Clima?', 'O Tempo é o estado momentâneo da atmosfera (ex: chovendo hoje); o Clima é o padrão das condições atmosféricas observado ao longo de muitos anos.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 143, 'Onde se encontra a maior parte da água doce líquida disponível para uso humano no planeta?', 'Nas águas subterrâneas (aqüíferos e lençóis freáticos).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 144, 'O que caracteriza um bioma?', 'É uma grande comunidade de plantas e animais adaptada às condições climáticas e de solo de uma região específica.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 145, 'Quem criou o conceito dos Domínios Morfoclimáticos no Brasil?', 'geógrafo Aziz Ab\'Saber.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 146, 'O que é o processo de intemperismo na formação dos solos?', 'É o desgaste e a desintegração das rochas por ação da água, do vento, da temperatura e dos seres vivos.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 147, 'Qual é a diferença principal entre a agricultura intensiva e a extensiva?', 'A intensiva usa alta tecnologia, adubos e máquinas avançadas; a extensiva utiliza técnicas mais tradicionais e menor uso de tecnologia.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 148, 'O que são as indústrias de bens de consumo?', 'São indústrias que fabricam produtos diretamente para o uso da população (podem ser duráveis, como carros, ou não duráveis, como alimentos e roupas).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 149, 'O que é o fenômeno da conurbação nas cidades?', ': É a união física entre duas ou mais cidades devido ao crescimento urbano, fazendo com que pareçam uma única grande área.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 150, 'Qual é a principal causa do aquecimento global antropogênico (provocado pelo homem)?', 'A emissão excessiva de gases de efeito estufa (como o gás carbônico) gerada pela queima de combustíveis fósseis e desmatamento.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 151, 'Qual é a diferença entre fontes de energia renováveis e não renováveis?', 'As renováveis se regeneram naturalmente (como solar e eólica); as não renováveis são finitas e podem se esgotar (como petróleo e carvão mineral).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 152, 'O que significa o conceito de Êxodo Rural?', 'É o movimento migratório de pessoas saindo do campo (zona rural) para morar nas cidades (zona urbana).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 153, 'O que significa pluralismo religioso em uma sociedade?', 'É a convivência pacífica e o respeito entre diferentes religiões e crenças em um mesmo território.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 154, 'O que estuda a Geopolítica?', 'As relações de poder, influência e estratégias entre os países no cenário mundial.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 155, 'Qual é o objetivo principal de um Bloco Econômico?', 'Facilitar o comércio, reduzir tarifas alfandegárias e fortalecer a economia entre os países membros.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 156, 'Qual é a importância do setor de transportes para a economia global?', 'Ele integra mercados, permitindo a circulação rápida de matérias-primas, mercadorias e pessoas pelo mundo.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 157, 'Oficialmente, em quantas grandes regiões o território brasileiro é dividido pelo IBGE?', 'Em 5 regiões: Norte, Nordeste, Centro-Oeste, Sudeste e Sul.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 80, 'O que é uma carta formal em espanhol?', ': É um texto escrito usado para se comunicar com instituições ou autoridades, exigindo tratamento respeitoso e o uso da forma \"usted\" (o senhor/a senhora).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 81, 'Qual é a diferença básica entre os artigos definidos el e la?', 'El é usado para o masculino singular; La é usado para o feminino singular.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 82, 'Como se diz \"você\" de forma formal em espanhol?', 'Usa-se o pronome Usted.');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 83, 'O que expressa o Pretérito Indefinido em espanhol?', 'Expressa uma ação que ocorreu e foi totalmente concluída no passado (ex: fui, comió, hablaron).');
INSERT INTO `nextage`.`flashcards` (`id_flashcard`, `id_conteudo`, `pergunta`, `resposta`) VALUES (DEFAULT, 84, 'O que são falsos amigos (falsos cognatos) em espanhol?', 'São palavras que parecem muito com o português na escrita ou na pronúncia, mas têm significados totalmente diferentes (ex: vaso em espanhol significa copo, não vaso de plantas).');
